node -e "
const { parse } = require('./src/parse.js');

// Test ISO string
const d1 = parse('2024-01-15');
console.log('ISO date:', d1.toISOString());

// Test full ISO string with time
const d2 = parse('2024-01-15T10:30:00Z');
console.log('ISO datetime:', d2.toISOString());

// Test milliseconds since epoch
const d3 = parse('1705310400000');
console.log('Epoch ms:', d3.toISOString());

// Test invalid date
const d4 = parse('invalid');
console.log('Invalid date:', d4.toString());

// Test null/undefined
const d5 = parse(null);
console.log('Null input:', d5.toString());
"

node -e "
// Test what happens with epoch milliseconds as a string
console.log('new Date(\"1705310400000\"):', new Date('1705310400000'));
console.log('new Date(1705310400000):', new Date(1705310400000));
console.log('');
console.log('new Date(\"2024-01-15\"):', new Date('2024-01-15'));
"
